import React, { useState } from 'react';
import axios from 'axios';
import './ClienteManagement.css'; // Certifique-se de que o caminho está correto

const CreateCliente = () => {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [telefone, setTelefone] = useState('');
  const [error, setError] = useState('');

  const handleCreateCliente = async (e) => {
    e.preventDefault();

    if (!nome || !email || !telefone) {
      setError('Todos os campos são obrigatórios!');
      return;
    }

    try {
      const cliente = { nome, email, telefone };
      const response = await axios.post('http://localhost:8080/clientes', cliente);
      alert('Cliente criado com sucesso!');
      setNome('');
      setEmail('');
      setTelefone('');
      setError('');
    } catch (error) {
      console.error('Erro ao criar cliente:', error);
      alert('Erro ao criar cliente!');
    }
  };

  return (
    <div className="create-cliente-form">
      <h3>Criar Novo Cliente</h3>
      {error && <div className="error-message">{error}</div>}
      <form onSubmit={handleCreateCliente}>
        <input
          type="text"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
          placeholder="Nome"
          required
        />
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Email"
          required
        />
        <input
          type="tel"
          value={telefone}
          onChange={(e) => setTelefone(e.target.value)}
          placeholder="Telefone"
          required
        />
        <button type="submit">Criar Cliente</button>
      </form>
    </div>
  );
};

export default CreateCliente;
